150	    throw new Error(`OpenAI 호환 ${res.status}: ${msg}`);
151	  }
152	  const j = (await res.json()) as {
153	    choices?: { message?: { content?: string }; finish_reason?: string }[];
154	    usage?: { prompt_tokens?: number; completion_tokens?: number };
155	  };
156	  const choice = j.choices?.[0];
157	  if (choice?.finish_reason === "length") {
158	    throw new Error("LLM 출력이 최대 길이(max_tokens)에 도달해 응답이 잘렸습니다. 자료가 너무 큽니다 — 더 작게 나눠 올려주세요.");
159	  }
160	  const text = choice?.message?.content ?? "";
161	  if (!text) throw new Error("OpenAI 호환 공급자가 빈 응답을 반환했습니다.");
162	  let data: T;
163	  try {
164	    data = JSON.parse(text) as T;
165	  } catch {
166	    // 코드펜스 등 잡신호가 섞이면 첫 { … 마지막 } 구간만 추출해 재시도
167	    const m = text.match(/\{[\s\S]*\}/);
168	    if (!m) throw new Error(`OpenAI 호환 공급자가 유효한 JSON을 반환하지 않았습니다: ${text.slice(0, 200)}`);
169	    try { data = JSON.parse(m[0]) as T; } catch { throw new Error(`OpenAI 호환 공급자 JSON 파싱 실패: ${text.slice(0, 200)}`); }
170	  }
171	  const u = j.usage ?? {};
172	  return { data, usage: { inputTokens: u.prompt_tokens ?? 0, outputTokens: u.completion_tokens ?? 0 } };
173	}
