import type { Usage } from "./anthropic";

// OpenAI 호환(/chat/completions) 어댑터 — Groq·OpenRouter·Mistral·(유료)OpenAI 등 한 어댑터로.
// 기본값은 Groq(무료·초고속). ★주의: 데이터가 외부로 전송됨 → 비민감 자료만(UI 경고 배너 노출).
// 구조화 출력은 JSON 모드(response_format: json_object) + 스키마를 시스템 프롬프트에 명시해
// 공급자 간 호환성을 높인다(strict json_schema는 공급자/모델별 편차가 커 회피).

export function openaiCompatApiKey(): string | null {
  const v = process.env.OPENAI_COMPAT_API_KEY?.trim();
  return v ? v : null;
}
export function openaiCompatEnabled(): boolean {
  return openaiCompatApiKey() !== null;
}
export function openaiCompatBaseUrl(): string {
  return (process.env.OPENAI_COMPAT_BASE_URL?.trim() || "https://api.groq.com/openai/v1").replace(/\/+$/, "");
}
export function openaiCompatDefaultModel(): string {
  return process.env.OPENAI_COMPAT_MODEL?.trim() || "llama-3.3-70b-versatile";
}
// 선택기 라벨에 쓸 공급자 표시명(예: Groq, OpenRouter).
export function openaiCompatLabel(): string {
  return process.env.OPENAI_COMPAT_LABEL?.trim() || "Groq";
}

// 공급자가 여러 모델을 제공하므로(특히 Groq), 모델을 비전 능력·노출여부와 함께 큐레이션.
// primary=true 만 선택기에 노출. 나머지(백업)는 자동 폴백(lib/fallback.ts)으로만 쓰인다.
export interface OcModel { id: string; label: string; vision: boolean; primary: boolean }

// Groq 실측 가용 모델(2026-06 기준). gpt-oss·llama-3.3=텍스트, llama-4-scout=비전(멀티모달).
// ★선택기엔 1순위(primary)만 보이고, 한도(429) 시 백업이 자동 대체된다(lib/fallback.ts).
//   고품질 텍스트:  gpt-oss-120b(노출) → llama-3.3-70b → gpt-oss-20b (백업·숨김)
//   이미지/비전:    Gemini(노출) → llama-4-scout (Groq 백업·숨김)
const GROQ_CURATED: OcModel[] = [
  { id: "openai/gpt-oss-120b", label: "GPT-OSS 120B · 고품질 텍스트", vision: false, primary: true },
  { id: "llama-3.3-70b-versatile", label: "Llama 3.3 70B · 텍스트 백업·한국어", vision: false, primary: false },
  { id: "openai/gpt-oss-20b", label: "GPT-OSS 20B · 가벼운 텍스트 백업", vision: false, primary: false },
  { id: "meta-llama/llama-4-scout-17b-16e-instruct", label: "Llama 4 Scout · 이미지 백업", vision: true, primary: false },
];

function guessVision(id: string): boolean {
  return /vision|llama-4|scout|maverick|llava|gpt-4o|gemini/i.test(id);
}

// OpenAI 호환 모델 전체(선택기 노출 + 폴백 대상 + 업로드 정책 산정에 사용).
//   - OPENAI_COMPAT_MODEL 고정 시: 그 모델 하나만(primary).
//   - 미고정 + Groq 엔드포인트: 큐레이션 목록(1순위 + 숨김 백업).
//   - 미고정 + 그 외 엔드포인트: 기본 모델 하나(primary, 비전은 이름으로 추정).
export function openaiCompatModels(): OcModel[] {
  const pin = process.env.OPENAI_COMPAT_MODEL?.trim();
  if (pin) return [{ id: pin, label: pin, vision: guessVision(pin), primary: true }];
  if (openaiCompatBaseUrl().includes("groq")) return GROQ_CURATED;
  const d = openaiCompatDefaultModel();
  return [{ id: d, label: d, vision: guessVision(d), primary: true }];
}

// 특정 모델이 비전(이미지/스캔본) 입력을 처리할 수 있는가.
export function openaiCompatModelVision(id: string): boolean {
  const found = openaiCompatModels().find((m) => m.id === id);
  return found ? found.vision : guessVision(id);
}

export interface OpenAICompatOpts {
  model: string;
  system: string;
  userText: string;
  schema: Record<string, unknown>;
  maxTokens?: number;
  images?: { mediaType: string; dataBase64: string }[];
  documents?: { mediaType: string; dataBase64: string }[];
}

// ── 공급자(Groq) 실시간 잔여 — 응답 헤더 캡처(docs/PLAN-usage-visibility §A) ──────────
// Groq는 모든 응답(성공·429·413) 헤더에 ★키(프로젝트) 전체 기준★ 잔여를 준다 → 같은 키를 배포+로컬이
// 같이 써도 공급자가 자동 합산한 실잔여가 반영된다(앱 DB 합산 불필요). 단 ★분당 스냅샷·마지막 호출 시점★
// 이고 RPD(일일)는 헤더에 없어 — 정확 누적은 콘솔이 기준(=여전히 추정 보조지표).
export interface ProviderRateLimit {
  model: string;
  limitRequests: number | null; remainingRequests: number | null; resetRequests: string | null;
  limitTokens: number | null; remainingTokens: number | null; resetTokens: string | null;
  at: string; // 이 스냅샷을 받은 시각(ISO) — '얼마나 최신인가' 표시용
}
// ★globalThis에 둔다★ — Next는 라우트 핸들러마다 모듈 인스턴스를 분리할 수 있어, 모듈 지역변수면
// /api/chat이 채운 캐시를 /api/account가 못 본다(Prisma 싱글톤과 동일 이유). 전역에 고정해 프로세스 공유.
const rateStore = globalThis as unknown as { __llmwikiRate?: Map<string, ProviderRateLimit> };
rateStore.__llmwikiRate ??= new Map<string, ProviderRateLimit>();
const rateByModel = rateStore.__llmwikiRate;
/** 이 프로세스가 마지막으로 받은 모델별 공급자 잔여 스냅샷(없으면 빈 배열). 인스턴스 메모리 캐시. */
export function providerRateLimits(): ProviderRateLimit[] {
  return Array.from(rateByModel.values());
}
function captureRateLimit(model: string, h: Headers): void {
  const num = (k: string) => { const v = h.get(k); if (v == null || v === "") return null; const n = Number(v); return Number.isFinite(n) ? n : null; };
  const limR = num("x-ratelimit-limit-requests"), remR = num("x-ratelimit-remaining-requests");
  const limT = num("x-ratelimit-limit-tokens"), remT = num("x-ratelimit-remaining-tokens");
  if (limR == null && remR == null && limT == null && remT == null) return; // 헤더 없는 공급자(OpenRouter 등)는 무시
  rateByModel.set(model, {
    model,
    limitRequests: limR, remainingRequests: remR, resetRequests: h.get("x-ratelimit-reset-requests") || null,
    limitTokens: limT, remainingTokens: remT, resetTokens: h.get("x-ratelimit-reset-tokens") || null,
    at: new Date().toISOString(),
  });
}

export async function openaiCompatStructured<T>(opts: OpenAICompatOpts): Promise<{ data: T; usage: Usage }> {
  const key = openaiCompatApiKey();
  if (!key) throw new Error("OPENAI_COMPAT_API_KEY 미설정 — Groq 등 OpenAI 호환 공급자를 쓰려면 키가 필요합니다(console.groq.com에서 발급).");
  const base = openaiCompatBaseUrl();

  // 구조화 출력: JSON 모드 + 스키마를 프롬프트로 강제(프롬프트에 'JSON' 단어 포함 필수).
  const system = `${opts.system}\n\n반드시 아래 JSON 스키마에 맞는 유효한 JSON 객체 하나만 출력하세요. 코드펜스(\`\`\`)·설명 없이 JSON만:\n${JSON.stringify(opts.schema)}`;

  // 비전(이미지) — OpenAI 호환 image_url(data URL). PDF/문서는 대부분 미지원이라 무시.
  const userContent: unknown = opts.images && opts.images.length
    ? [
        { type: "text", text: opts.userText },
        ...opts.images.map((im) => ({ type: "image_url", image_url: { url: `data:${im.mediaType};base64,${im.dataBase64}` } })),
      ]
    : opts.userText;

  let res: Response;
  try {
    res = await fetch(`${base}/chat/completions`, {
      method: "POST",
      headers: { "content-type": "application/json", authorization: `Bearer ${key}` },
      body: JSON.stringify({
        model: opts.model,
        messages: [
          { role: "system", content: system },
          { role: "user", content: userContent },
        ],
        response_format: { type: "json_object" },
        max_tokens: opts.maxTokens ?? 8192,
        temperature: 0,
      }),
    });
  } catch (e) {
    throw new Error(`OpenAI 호환 공급자 연결 실패: ${String(e)}`);
  }
  captureRateLimit(opts.model, res.headers); // 성공·429·413 모두 헤더에 잔여가 실림 → throw 전에 캡처
  if (!res.ok) {
    const body = await res.text().catch(() => "");
    // Groq 등은 {"error":{"message":"..."}} → 핵심 message만 뽑아 ★잘림 없이★ 보여준다(평문이면 적당히 자름).
    let msg = body.slice(0, 400);
    try { const j = JSON.parse(body); if (j?.error?.message) msg = String(j.error.message); } catch { /* 평문 → slice 유지 */ }
    if (res.status === 401) throw new Error(`인증 실패(401) — OPENAI_COMPAT_API_KEY를 확인하세요. ${msg}`);
    if (res.status === 404) throw new Error(`모델 '${opts.model}' 없음 — OPENAI_COMPAT_MODEL을 현행 모델명으로 설정하세요(예: llama-3.3-70b-versatile, openai/gpt-oss-20b). ${msg}`);
    if (res.status === 429) throw new Error(`사용량 한도 초과(429·무료 등급). 잠시 후 다시 시도하세요. ${msg}`);
    if (res.status === 413) throw new Error(`자료가 너무 큽니다(413) — 이 모델의 분당 토큰(TPM) 한도를 초과했습니다. 더 작게 나눠 올리거나 '원본 그대로 추가'를 쓰세요. ${msg}`);
    throw new Error(`OpenAI 호환 ${res.status}: ${msg}`);
  }
  const j = (await res.json()) as {
    choices?: { message?: { content?: string }; finish_reason?: string }[];
    usage?: { prompt_tokens?: number; completion_tokens?: number };
  };
  const choice = j.choices?.[0];
  if (choice?.finish_reason === "length") {
    throw new Error("LLM 출력이 최대 길이(max_tokens)에 도달해 응답이 잘렸습니다. 자료가 너무 큽니다 — 더 작게 나눠 올려주세요.");
  }
  const text = choice?.message?.content ?? "";
  if (!text) throw new Error("OpenAI 호환 공급자가 빈 응답을 반환했습니다.");
  let data: T;
  try {
    data = JSON.parse(text) as T;
  } catch {
    // 코드펜스 등 잡신호가 섞이면 첫 { … 마지막 } 구간만 추출해 재시도
    const m = text.match(/\{[\s\S]*\}/);
    if (!m) throw new Error(`OpenAI 호환 공급자가 유효한 JSON을 반환하지 않았습니다: ${text.slice(0, 200)}`);
    try { data = JSON.parse(m[0]) as T; } catch { throw new Error(`OpenAI 호환 공급자 JSON 파싱 실패: ${text.slice(0, 200)}`); }
  }
  const u = j.usage ?? {};
  return { data, usage: { inputTokens: u.prompt_tokens ?? 0, outputTokens: u.completion_tokens ?? 0 } };
}

