/**
 * 질의 루프(docs/07 §1). Phase 1은 common 단일 scope(ACL 사전필터는 Phase 2).
 * 답변 후 Q&A를 queries/YYYY-MM/q-NNNNNN.md로 append-only 커밋해 같은 팀이 재사용(A→B 누적).
 */
export async function answerQuery(input: QueryInput): Promise<QueryResult> {
  await assertWikiReady();
  const scope = input.scope ?? "common";

  // 질문 임베딩 1회(④) — 페이지 의미정렬(①)에 사용. 임베딩 불가면 null → 키워드 폴백.
  const qVec = await embedOne(input.question);

  // ② 재사용 캐시: 대화 맥락 없는(독립) 질문이면 최근 동일 문구 질문의 답을 재사용(LLM 호출·토큰 0).
  //   맥락 의존 질문(history 있음)은 재사용 안 함. (안전상 정확/유사 문구만 — tryReuseAnswer 주석)
  if (!input.history?.length) {
    const reuse = await tryReuseAnswer(scope, input.question);
    if (reuse) {
      return {
        queryId: reuse.queryId, answered: true, answerMd: reuse.answerMd, citedPaths: reuse.citedPaths,
        filedPath: "", commitSha: "", usage: { inputTokens: 0, outputTokens: 0 },
        usedModel: "재사용(캐시)", reused: true,
      };
    }
  }

  // 컨텍스트 로드: 두뇌 + 목차 + 페이지(질의기록 포함 → 재사용)
  const [brain, index, pages] = await Promise.all([
    loadBrain(),
    loadIndex(scope),
    loadPages(scope, ["entities", "concepts", "topics", "queries"]),
  ]);

  // ★컨텍스트 한정(①)★ + ★의미검색(④)★: 질문 관련 페이지만(임베딩 코사인 정렬, 폴백 키워드).
  // 양은 ★서빙 모델별 예산(ctxBudgetFor)★으로 조절 — Gemini/Claude는 넉넉히, Groq는 무료 TPM에 맞춰 타이트.
  const queryProvider = input.provider ?? providerFor("query");
  const queryModel = input.model ?? MODELS.query;
  const disabledModels = await disabledModelIds(); // 관리자가 끈 모델은 폴백 후보에서 제외
  const ranked = await rankPages(scope, pages, input.question, qVec); // 관련도 순(의미 or 키워드)
  const build = (ctx: { model: string; provider: string; tier: PromptTier; scale: number }): BuiltPrompt => {
    const lim = ctxBudgetFor(ctx.provider, ctx.model, ctx.scale);
    return {
      system: buildSystem(brain),
      userText: buildUser(input.question, index, takePages(ranked, lim.maxPages, lim.maxChars), input.history),
      toolName: "submit_answer",
      toolDescription: "위키를 근거로 한 출처 인용 답변.",
      schema: ANSWER_SCHEMA,
      maxTokens: 4096,
    };
  };
  const { data, usage, model: servedModel, provider: servedProvider, fallback: fallbackInfo } = await callStructured<{
    answered: boolean;
    answer_md: string;
    cited_paths: string[];
  }>({
    model: queryModel,
    provider: queryProvider,
    think: input.think ?? false,
    fallbacks: fallbackChainFor(queryModel, queryProvider).filter((f) => !disabledModels.has(f.model)),
    build,
  });

  // 인용 경로 검증: scope 안 + ★서빙 모델이 실제로 본 페이지★(서빙 모델 예산으로 재계산)만 신뢰(ACL/환각 방지).
  const servedLim = ctxBudgetFor(servedProvider, servedModel);
  const usedPages = takePages(ranked, servedLim.maxPages, servedLim.maxChars);
  const knownPaths = new Set(usedPages.map((p) => p.path));
  const citedPaths = (data.cited_paths ?? []).filter((p) => {
    try {
      assertInScope(scope, p);
    } catch {
      return false;
    }
    return knownPaths.has(p);
  });

  // query_log 먼저 insert → id로 파일명 부여.
  const log = await prisma.queryLog.create({
    data: {
      userId: input.userId ?? null,
      teamScope: scope,
      question: input.question,
      answerMd: data.answer_md,
      citedPaths: JSON.stringify(citedPaths),
      inputTokens: usage.inputTokens,
      outputTokens: usage.outputTokens,
      visibility: "TEAM",
    },
  });

  const now = new Date();
  const ym = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`;
  const filedRel = `${scope}/queries/${ym}/q-${String(log.id).padStart(6, "0")}.md`;

  const pageMd =
    frontmatter({
      title: input.question.replace(/\n/g, " ").slice(0, 80),
      type: "query",
      scope,
      sources: JSON.stringify(citedPaths),
      updated: now.toISOString().slice(0, 10),
    }) +
    `\n## 질문\n${input.question}\n\n## 답변\n${data.answer_md}\n\n## 인용\n` +
    (citedPaths.length ? citedPaths.map((p) => `- ${p}`).join("\n") : "- (없음 — 위키에 근거 없음)") +
    "\n";

  const commitSha = await withWikiWriteLock(async () => {
    const abs = wikiAbsPath(filedRel);
    await fs.mkdir(path.dirname(abs), { recursive: true });
    await fs.writeFile(abs, pageMd, "utf8");
    return commitAll(`query(${scope}): ${input.question.slice(0, 60)}`, {
      team: scope,
      sourceType: "CHAT",
      model: MODELS.query,
    });
  });

  await prisma.queryLog.update({
    where: { id: log.id },
    data: { filedPath: filedRel },
  });

  await recordUsage({ userId: input.userId, scope, kind: "query", model: servedModel, inputTokens: usage.inputTokens, outputTokens: usage.outputTokens });

  return {
    queryId: log.id,
    answered: data.answered,
    answerMd: data.answer_md,
    citedPaths,
    filedPath: filedRel,
    commitSha,
    usage,
    usedModel: servedModel,
    fallback: fallbackInfo, // 1순위 대체 시 {fromModel, reason}
  };
}

