1	import { prisma } from "./db";
2	
3	// 비용 통제: LLM 토큰 사용 집계 + 사용자 1일 상한 (REQ-OPS-002·006, docs/15 §4).
4	const DAILY_LIMIT = Number(process.env.DAILY_TOKEN_LIMIT || 0); // 0 = 무제한
5	const WARN_RATIO = 0.8;
6	
7	export type UsageKind = "query" | "ingest" | "websearch";
8	
9	/** 토큰 사용 1건 기록(집계 실패가 본 기능을 막지 않도록 swallow). */
10	export async function recordUsage(input: {
11	  userId?: number | null;
12	  scope: string;
13	  kind: UsageKind;
14	  model?: string | null;
15	  inputTokens: number;
16	  outputTokens: number;
17	}): Promise<void> {
18	  try {
19	    await prisma.tokenUsage.create({
20	      data: {
21	        userId: input.userId ?? null,
22	        teamScope: input.scope,
23	        kind: input.kind,
24	        model: input.model ?? null,
25	        inputTokens: input.inputTokens || 0,
26	        outputTokens: input.outputTokens || 0,
27	      },
28	    });
29	  } catch {
30	    /* 집계 실패 무시 */
31	  }
32	}
33	
34	function startOfTodayUTC(): Date {
35	  const n = new Date();
36	  return new Date(Date.UTC(n.getUTCFullYear(), n.getUTCMonth(), n.getUTCDate()));
37	}
38	
39	/** 기록된 모델명으로 공급자 추정(UI 라벨·색상용). gemini·claude 접두 외엔 로컬로 본다. */
40	function providerOfModel(model: string): "gemini" | "anthropic" | "ollama" | "codex" | "unknown" {
41	  if (!model || model === "(기타)") return "unknown";
42	  const m = model.toLowerCase();
43	  if (m.startsWith("gemini")) return "gemini";
44	  if (m.startsWith("claude")) return "anthropic";
45	  if (m === "codex") return "codex"; // codex CLI(구독)
46	  return "ollama"; // qwen/llama/deepseek 등 로컬
47	}
48	
49	// 공급자 무료등급 일일 ★요청 수★ 한도(근사 — 무료 한도는 토큰이 아니라 요청수 기준, 공급자 정책에 따라 변동).
50	// env로 조정: GEMINI_DAILY_REQUESTS / GROQ_DAILY_REQUESTS. requests=0 = 한도 표시 안 함(무제한/유료).
51	export function providerDailyLimit(provider: string): { requests: number; plan: string } {
52	  if (provider === "gemini") return { requests: Number(process.env.GEMINI_DAILY_REQUESTS || 250), plan: "무료" };
53	  if (provider === "openai-compat") return { requests: Number(process.env.GROQ_DAILY_REQUESTS || 1000), plan: "무료" };
54	  if (provider === "anthropic") return { requests: Number(process.env.ANTHROPIC_DAILY_REQUESTS || 0), plan: "유료" };
55	  // codex = ChatGPT 구독: 실제 한도는 5시간/주간 창이라 헤드리스로 못 읽는다(잔여는 /status·웹). 토큰/요청수는 집계.
56	  //   CODEX_DAILY_REQUESTS를 주면 그 값을 ★근사 일일 한도★로 막대 표시(공유 계정 과사용 방지 가이드용). 기본 0=막대 없음.
57	  if (provider === "codex") return { requests: Number(process.env.CODEX_DAILY_REQUESTS || 0), plan: "구독(ChatGPT)" };
58	  return { requests: 0, plan: "로컬·무제한" }; // ollama
59	}
60	
61	export interface ModelUsageRow { model: string; provider: string; tokens: number; requests: number; reqLimit: number; plan: string; disabled?: boolean; kind?: "primary" | "backup" }
62	
63	/**
64	 * 모델별 사용량 게이지 보정(설정 화면용):
65	 *  ① 실제 사용행의 공급자를 ★모델 목록의 정확한 provider★로 교정(이름 추정으로 Groq를 ollama로 오인하던 것 수정).
66	 *  ② ★사용량 0인 모델도 행으로 추가★해 게이지가 늘 보이게(오늘 안 써도 한도 막대가 보이도록).
67	 * available = listQueryModels() 결과(공급자 정확). 공급자 키가 있는(available) 모델은 1순위·백업 모두 게이지에
68	 * 표시한다(무료 한도가 ★모델별★이라 — Groq는 모델마다 RPD 별개 — 모델 단위로 보여주는 게 정확·직관). backup은
69	 * 'backup' kind로 구분. 관리자가 꺼도(disabled) '꺼짐'으로 함께 표시. 키 없는(미가용) 모델·#think 변형은 제외.
70	 */
71	export function reconcileModelUsage(
72	  byModel: ModelUsageRow[],
73	  available: { id: string; provider: string; kind?: string; enabled?: boolean; available?: boolean }[],
74	): ModelUsageRow[] {
75	  const provById = new Map(available.map((m) => [m.id, m.provider]));
76	  const kindById = new Map(available.map((m) => [m.id, ((m.kind as "primary" | "backup") ?? "primary")]));
77	  const disabledIds = new Set(available.filter((m) => m.enabled === false).map((m) => m.id)); // 관리자가 끔
78	  const fixed = byModel.map((r) => {
79	    const prov = provById.get(r.model) ?? r.provider;
80	    const disabled = disabledIds.has(r.model) || undefined;
81	    const kind = kindById.get(r.model);
82	    if (prov === r.provider) return { ...r, disabled, kind };
83	    const lim = providerDailyLimit(prov);
84	    return { ...r, provider: prov, reqLimit: lim.requests, plan: lim.plan, disabled, kind };
85	  });
86	  const used = new Set(fixed.map((r) => r.model));
87	  const zeros: ModelUsageRow[] = available
88	    // 0행: ★가용(키 있음)·미사용★ 모든 모델(1순위+백업). '#think'(추론 변형)은 같은 모델·같은 한도라 중복 제외(사용량은 base로만 기록).
89	    // 관리자가 끈(enabled=false) 가용 모델도 포함하되 disabled로 표시(전체 라인업 가시화).
90	    .filter((m) => m.available !== false && !m.id.endsWith("#think") && !used.has(m.id))
91	    .map((m) => {
92	      const lim = providerDailyLimit(m.provider);
93	      return { model: m.id, provider: m.provider, tokens: 0, requests: 0, reqLimit: lim.requests, plan: lim.plan, disabled: m.enabled === false || undefined, kind: ((m.kind as "primary" | "backup") ?? "primary") };
94	    });
95	  // ★게이지 순서를 '모델 관리' 토글 목록(= available = listQueryModels)과 동일하게★ 맞춘다(사용·0행 통합 후
96	  //   available 등장 순서로 정렬). 목록에 없는 모델(드묾)은 맨 뒤. — 두 목록 순서 일치 요구.
97	  const orderById = new Map(available.map((m, i) => [m.id, i] as const));
98	  return [...fixed, ...zeros].sort((a, b) => (orderById.get(a.model) ?? 1e9) - (orderById.get(b.model) ?? 1e9));
99	}
100	
101	export interface BudgetStatus { used: number; limit: number; exceeded: boolean; warn: boolean }
102	
103	/** 오늘(UTC) 사용자 토큰 합계 vs 상한. limit=0이면 항상 통과. */
104	export async function checkDailyBudget(userId: number): Promise<BudgetStatus> {
105	  if (!DAILY_LIMIT) return { used: 0, limit: 0, exceeded: false, warn: false };
106	  const agg = await prisma.tokenUsage.aggregate({
