import { prisma } from "./db";

// 비용 통제: LLM 토큰 사용 집계 + 사용자 1일 상한 (REQ-OPS-002·006, docs/15 §4).
const DAILY_LIMIT = Number(process.env.DAILY_TOKEN_LIMIT || 0); // 0 = 무제한
const WARN_RATIO = 0.8;

export type UsageKind = "query" | "ingest" | "websearch";

/** 토큰 사용 1건 기록(집계 실패가 본 기능을 막지 않도록 swallow). */
export async function recordUsage(input: {
  userId?: number | null;
  scope: string;
  kind: UsageKind;
  model?: string | null;
  inputTokens: number;
  outputTokens: number;
}): Promise<void> {
  try {
    await prisma.tokenUsage.create({
      data: {
        userId: input.userId ?? null,
        teamScope: input.scope,
        kind: input.kind,
        model: input.model ?? null,
        inputTokens: input.inputTokens || 0,
        outputTokens: input.outputTokens || 0,
      },
    });
  } catch {
    /* 집계 실패 무시 */
  }
}

function startOfTodayUTC(): Date {
  const n = new Date();
  return new Date(Date.UTC(n.getUTCFullYear(), n.getUTCMonth(), n.getUTCDate()));
}

/** 기록된 모델명으로 공급자 추정(UI 라벨·색상용). gemini·claude 접두 외엔 로컬로 본다. */
function providerOfModel(model: string): "gemini" | "anthropic" | "ollama" | "codex" | "unknown" {
  if (!model || model === "(기타)") return "unknown";
  const m = model.toLowerCase();
  if (m.startsWith("gemini")) return "gemini";
  if (m.startsWith("claude")) return "anthropic";
  if (m === "codex") return "codex"; // codex CLI(구독)
  return "ollama"; // qwen/llama/deepseek 등 로컬
}

// 공급자 무료등급 일일 ★요청 수★ 한도(근사 — 무료 한도는 토큰이 아니라 요청수 기준, 공급자 정책에 따라 변동).
// env로 조정: GEMINI_DAILY_REQUESTS / GROQ_DAILY_REQUESTS. requests=0 = 한도 표시 안 함(무제한/유료).
export function providerDailyLimit(provider: string): { requests: number; plan: string } {
  if (provider === "gemini") return { requests: Number(process.env.GEMINI_DAILY_REQUESTS || 250), plan: "무료" };
  if (provider === "openai-compat") return { requests: Number(process.env.GROQ_DAILY_REQUESTS || 1000), plan: "무료" };
  if (provider === "anthropic") return { requests: Number(process.env.ANTHROPIC_DAILY_REQUESTS || 0), plan: "유료" };
  // codex = ChatGPT 구독: 실제 한도는 5시간/주간 창이라 헤드리스로 못 읽는다(잔여는 /status·웹). 토큰/요청수는 집계.
  //   CODEX_DAILY_REQUESTS를 주면 그 값을 ★근사 일일 한도★로 막대 표시(공유 계정 과사용 방지 가이드용). 기본 0=막대 없음.
  if (provider === "codex") return { requests: Number(process.env.CODEX_DAILY_REQUESTS || 0), plan: "구독(ChatGPT)" };
  return { requests: 0, plan: "로컬·무제한" }; // ollama
}

export interface ModelUsageRow { model: string; provider: string; tokens: number; requests: number; reqLimit: number; plan: string; disabled?: boolean; kind?: "primary" | "backup" }

/**
 * 모델별 사용량 게이지 보정(설정 화면용):
 *  ① 실제 사용행의 공급자를 ★모델 목록의 정확한 provider★로 교정(이름 추정으로 Groq를 ollama로 오인하던 것 수정).
 *  ② ★사용량 0인 모델도 행으로 추가★해 게이지가 늘 보이게(오늘 안 써도 한도 막대가 보이도록).
 * available = listQueryModels() 결과(공급자 정확). 공급자 키가 있는(available) 모델은 1순위·백업 모두 게이지에
 * 표시한다(무료 한도가 ★모델별★이라 — Groq는 모델마다 RPD 별개 — 모델 단위로 보여주는 게 정확·직관). backup은
 * 'backup' kind로 구분. 관리자가 꺼도(disabled) '꺼짐'으로 함께 표시. 키 없는(미가용) 모델·#think 변형은 제외.
 */
export function reconcileModelUsage(
  byModel: ModelUsageRow[],
  available: { id: string; provider: string; kind?: string; enabled?: boolean; available?: boolean }[],
): ModelUsageRow[] {
  const provById = new Map(available.map((m) => [m.id, m.provider]));
  const kindById = new Map(available.map((m) => [m.id, ((m.kind as "primary" | "backup") ?? "primary")]));
  const disabledIds = new Set(available.filter((m) => m.enabled === false).map((m) => m.id)); // 관리자가 끔
  const fixed = byModel.map((r) => {
    const prov = provById.get(r.model) ?? r.provider;
    const disabled = disabledIds.has(r.model) || undefined;
    const kind = kindById.get(r.model);
    if (prov === r.provider) return { ...r, disabled, kind };
    const lim = providerDailyLimit(prov);
    return { ...r, provider: prov, reqLimit: lim.requests, plan: lim.plan, disabled, kind };
  });
  const used = new Set(fixed.map((r) => r.model));
  const zeros: ModelUsageRow[] = available
    // 0행: ★가용(키 있음)·미사용★ 모든 모델(1순위+백업). '#think'(추론 변형)은 같은 모델·같은 한도라 중복 제외(사용량은 base로만 기록).
    // 관리자가 끈(enabled=false) 가용 모델도 포함하되 disabled로 표시(전체 라인업 가시화).
    .filter((m) => m.available !== false && !m.id.endsWith("#think") && !used.has(m.id))
    .map((m) => {
      const lim = providerDailyLimit(m.provider);
      return { model: m.id, provider: m.provider, tokens: 0, requests: 0, reqLimit: lim.requests, plan: lim.plan, disabled: m.enabled === false || undefined, kind: ((m.kind as "primary" | "backup") ?? "primary") };
    });
  // ★게이지 순서를 '모델 관리' 토글 목록(= available = listQueryModels)과 동일하게★ 맞춘다(사용·0행 통합 후
  //   available 등장 순서로 정렬). 목록에 없는 모델(드묾)은 맨 뒤. — 두 목록 순서 일치 요구.
  const orderById = new Map(available.map((m, i) => [m.id, i] as const));
  return [...fixed, ...zeros].sort((a, b) => (orderById.get(a.model) ?? 1e9) - (orderById.get(b.model) ?? 1e9));
}

export interface BudgetStatus { used: number; limit: number; exceeded: boolean; warn: boolean }

/** 오늘(UTC) 사용자 토큰 합계 vs 상한. limit=0이면 항상 통과. */
export async function checkDailyBudget(userId: number): Promise<BudgetStatus> {
  if (!DAILY_LIMIT) return { used: 0, limit: 0, exceeded: false, warn: false };
  const agg = await prisma.tokenUsage.aggregate({
    where: { userId, createdAt: { gte: startOfTodayUTC() } },
    _sum: { inputTokens: true, outputTokens: true },
  });
  const used = (agg._sum.inputTokens ?? 0) + (agg._sum.outputTokens ?? 0);
  return { used, limit: DAILY_LIMIT, exceeded: used >= DAILY_LIMIT, warn: used >= DAILY_LIMIT * WARN_RATIO };
}

/** 대시보드용 요약: 오늘 합계·종류별·최근 N일 일별, (ADMIN) 전체 오늘 합계. */
export async function usageSummary(userId: number, isAdmin: boolean) {
  const since = new Date(Date.now() - 7 * 86400 * 1000);
  const mine = await prisma.tokenUsage.findMany({
    where: { userId, createdAt: { gte: since } },
    select: { kind: true, model: true, inputTokens: true, outputTokens: true, createdAt: true },
  });
  const today = startOfTodayUTC();
  const byKind: Record<string, number> = {};
  const byDay: Record<string, number> = {};
  const byModel: Record<string, { tokens: number; requests: number }> = {}; // 오늘, 모델별
  let todayTotal = 0;
  for (const r of mine) {
    const tot = (r.inputTokens || 0) + (r.outputTokens || 0);
    byKind[r.kind] = (byKind[r.kind] || 0) + tot;
    const day = r.createdAt.toISOString().slice(0, 10);
    byDay[day] = (byDay[day] || 0) + tot;
    if (r.createdAt >= today) {
      todayTotal += tot;
      const k = r.model || "(기타)";
      if (!byModel[k]) byModel[k] = { tokens: 0, requests: 0 };
      byModel[k].tokens += tot;
      byModel[k].requests += 1; // 호출 1건 = 요청 1
    }
  }
  let adminTodayTotal: number | null = null;
  if (isAdmin) {
    const agg = await prisma.tokenUsage.aggregate({
      where: { createdAt: { gte: today } },
      _sum: { inputTokens: true, outputTokens: true },
    });
    adminTodayTotal = (agg._sum.inputTokens ?? 0) + (agg._sum.outputTokens ?? 0);
  }
  return {
    todayTotal,
    limit: DAILY_LIMIT,
    byKind,
    byDay: Object.entries(byDay).sort((a, b) => a[0].localeCompare(b[0])),
    byModel: Object.entries(byModel)
      .map(([model, v]): ModelUsageRow => {
        const provider = providerOfModel(model);
        const lim = providerDailyLimit(provider);
        return { model, provider, tokens: v.tokens, requests: v.requests, reqLimit: lim.requests, plan: lim.plan };
      })
      .sort((a, b) => b.tokens - a.tokens),
    adminTodayTotal,
  };
}

