import { NextResponse } from "next/server";
import { getSessionUser } from "@/lib/auth/session";
import { allowedScopes } from "@/lib/acl/scope";
import { usageSummary, reconcileModelUsage } from "@/lib/cost";
import { listQueryModels } from "@/lib/models";
import { providerRateLimits } from "@/lib/openai-compat";

// 계정 설정 모달용 데이터(프로필·워크스페이스·토큰 사용량·모델 관리). /settings 페이지와 동일.
export const runtime = "nodejs";

export async function GET() {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  const isAdmin = user.role === "ADMIN";
  const [scopes, usage, models] = await Promise.all([allowedScopes(user), usageSummary(user.id, isAdmin), listQueryModels()]);
  usage.byModel = reconcileModelUsage(usage.byModel ?? [], models); // 사용 0인 모델도 게이지에 표시 + 공급자 교정
  return NextResponse.json({
    profile: {
      name: user.name ?? user.email,
      email: user.email,
      role: user.role,
      isAdmin,
      isSso: Boolean(user.ssoSubject),
      verified: Boolean(user.emailVerifiedAt),
      createdAt: user.createdAt.toISOString(),
      initials: (user.name ?? user.email).slice(0, 1).toUpperCase(),
    },
    scopes: scopes.map((s) => ({ id: s.id, kind: s.kind, name: s.name, isOwner: Boolean(s.isOwner) })),
    usage,
    models, // 모델 관리(관리자 토글)용 전체 목록
    providerLive: providerRateLimits(), // 공급자(Groq) 실시간 잔여 스냅샷 — 키 전체 기준(합산 반영)
  });
}

