10	type ScopeKind = "common" | "personal" | "project";
11	interface ScopeLite { id: string; kind: ScopeKind; name: string; isOwner: boolean }
12	interface Profile {
13	  name: string; email: string; role: string; isAdmin?: boolean;
14	  isSso: boolean; verified: boolean; createdAt: string; initials: string;
15	}
16	interface ModelLite {
17	  id: string; label: string; provider: string; enabled: boolean;
18	  kind?: "primary" | "backup"; backupOf?: string; available?: boolean; adminDisabled?: boolean; note?: string;
19	}
20	interface ModelUsage { model: string; tokens: number; provider: string; requests?: number; reqLimit?: number; plan?: string; disabled?: boolean; kind?: "primary" | "backup" }
21	interface Usage {
22	  todayTotal: number; limit: number;
23	  byKind: Record<string, number>;
24	  byDay: [string, number][];
25	  byModel?: ModelUsage[];
26	  adminTodayTotal: number | null;
27	}
28	// 공급자(Groq) 실시간 잔여 스냅샷 — 키 전체 기준(배포+로컬 합산). 분당(RPM/TPM)·마지막 호출 시점.
29	interface ProviderLive {
30	  model: string;
31	  limitRequests: number | null; remainingRequests: number | null; resetRequests: string | null;
32	  limitTokens: number | null; remainingTokens: number | null; resetTokens: string | null;
33	  at: string;
34	}
35	const fmt = (n: number) => n.toLocaleString();
36	const KIND_LABEL: Record<string, string> = { query: "질의", ingest: "인제스트", websearch: "웹검색" };
37	// 공급자별 막대 색 + 표시 라벨(모델별 사용량 바)
38	const PROV_META: Record<string, { color: string; tag: string }> = {
39	  gemini: { color: "#f59e0b", tag: "외부·Google" },
40	  "openai-compat": { color: "#06b6d4", tag: "외부·Groq" },
41	  anthropic: { color: "#a855f7", tag: "Claude·유료" },
42	  ollama: { color: "#22c55e", tag: "사내·무료" },
43	  codex: { color: "#10a37f", tag: "구독·OpenAI" },
44	  unknown: { color: "var(--color-text-tertiary)", tag: "기타" },
45	};
