56	      <div className="set-row-key"><I size={15} />{label}</div>
57	      <div className="set-row-val">{children}</div>
58	    </div>
59	  );
60	}
61	
62	export default function SettingsView({ profile, scopes, usage: usageProp, models, providerLive, onClose }: { profile: Profile; scopes: ScopeLite[]; usage: Usage; models?: ModelLite[]; providerLive?: ProviderLive[]; onClose?: () => void }) {
63	  const [dark, setDark] = useState(false);
64	  useEffect(() => { setDark(document.documentElement.classList.contains("dark")); }, []);
65	
66	  // 사용량(게이지)은 상태로 — 모델 토글 후 재조회해 즉시 반영(prop은 모달/페이지 열릴 때 1회 계산이라 그대로 두면 stale).
67	  const [usage, setUsage] = useState<Usage>(usageProp);
68	  useEffect(() => { setUsage(usageProp); }, [usageProp]);
69	
70	  // 모델 관리(관리자 토글). 낙관적 업데이트로 즉시 반영(깜빡임·금지커서 방지), 실패 시 롤백.
71	  const [modelList, setModelList] = useState<ModelLite[]>(models || []);
72	  useEffect(() => { if (models) setModelList(models); }, [models]);
73	  async function toggleModel(id: string, enabled: boolean) {
74	    setModelList((list) => list.map((m) => (m.id === id ? { ...m, enabled, adminDisabled: !enabled } : m)));
75	    try {
76	      const res = await fetch("/api/admin/models", {
77	        method: "POST", headers: { "content-type": "application/json" },
78	        body: JSON.stringify({ modelId: id, enabled }),
79	      });
80	      const d = await res.json();
81	      if (res.ok && d.models) setModelList(d.models);
82	      else throw new Error();
83	      // ★게이지(usage.byModel)도 갱신★ — 켠/끈 모델이 사용량 막대에 즉시 반영되도록 계정 데이터 재조회.
84	      try {
85	        const acc = await fetch("/api/account", { cache: "no-store" });
86	        if (acc.ok) { const aj = await acc.json(); if (aj.usage) setUsage(aj.usage); if (aj.models) setModelList(aj.models); }
87	      } catch { /* 게이지 갱신 실패는 무시(토글 자체는 성공) */ }
88	    } catch {
89	      setModelList((list) => list.map((m) => (m.id === id ? { ...m, enabled: !enabled, adminDisabled: enabled } : m)));
90	    }
91	  }
92	
93	  function setTheme(next: boolean) {
94	    document.documentElement.classList.toggle("dark", next);
95	    document.cookie = `llmwiki_theme=${next ? "dark" : "light"}; path=/; max-age=31536000; samesite=lax`;
96	    setDark(next);
97	  }
98	
99	  const rooms = scopes.filter((s) => s.kind === "project");
100	
101	  const body = (
102	    <>
103	        {/* 프로필 */}
104	        <section className="set-card">
105	          <div className="set-card-head">프로필</div>
106	          <div className="set-profile">
107	            <div className="set-avatar">{profile.initials}</div>
108	            <div>
109	              <div className="set-name">{profile.name}</div>
110	              <div className="set-sub">{profile.email}</div>
111	            </div>
112	          </div>
113	          <div className="set-rows">
114	            <Row icon={IconMail} label="이메일">
115	              <span>{profile.email}</span>
116	              <span className="set-badge muted">인트라넷에서 관리</span>
117	            </Row>
118	            <Row icon={profile.role === "ADMIN" ? IconShieldCheck : IconShieldHalf} label="역할">
119	              <span className={`set-badge ${profile.role === "ADMIN" ? "accent" : "muted"}`}>
120	                {profile.role === "ADMIN" ? "관리자 (ADMIN)" : "일반 (USER)"}
121	              </span>
122	            </Row>
123	            <Row icon={IconId} label="계정 유형">
124	              {profile.isSso
125	                ? <span className="set-badge accent">인트라넷 SSO 계정</span>
126	                : <span className="set-badge muted">임시 계정</span>}
127	            </Row>
128	            <Row icon={IconCircleCheck} label="이메일 인증">
129	              {profile.verified
130	                ? <span className="set-ok"><IconCircleCheck size={14} />인증됨{profile.isSso ? " · 인트라넷" : ""}</span>
131	                : <span className="set-badge warn">미인증</span>}
132	            </Row>
133	            <Row icon={IconCalendar} label="가입일"><span>{profile.createdAt.slice(0, 10)}</span></Row>
134	          </div>
135	          <p className="set-note">이름·이메일은 인트라넷 SSO에서 동기화되어 이곳에서 수정할 수 없습니다.</p>
136	        </section>
137	
138	        {/* 표시 환경 */}
139	        <section className="set-card">
140	          <div className="set-card-head">표시 환경</div>
141	          <Row icon={dark ? IconMoon : IconSun} label="테마">
142	            <div className="set-seg">
143	              <button className={`set-seg-btn${!dark ? " active" : ""}`} onClick={() => setTheme(false)}>
144	                <IconSun size={14} />라이트
145	              </button>
146	              <button className={`set-seg-btn${dark ? " active" : ""}`} onClick={() => setTheme(true)}>
147	                <IconMoon size={14} />다크
148	              </button>
149	            </div>
150	          </Row>
151	          <p className="set-note">선택한 테마는 이 브라우저에 저장되어 다음 접속에도 유지됩니다.</p>
152	        </section>
153	
154	        {/* 토큰 사용량 (비용) */}
155	        <section className="set-card">
156	          <div className="set-card-head"><IconCoin size={14} style={{ verticalAlign: "-2px", marginRight: 5 }} />토큰 사용량</div>
157	          <Row icon={IconCoin} label="오늘 사용">
158	            <span style={{ fontWeight: 600 }}>{fmt(usage.todayTotal)}</span>
159	            <span style={{ color: "var(--color-text-tertiary)" }}>토큰{usage.limit > 0 ? ` / ${fmt(usage.limit)} 한도` : " (한도 없음)"}</span>
160	          </Row>
161	          {usage.limit > 0 && (
162	            <div className="cost-bar"><div className="cost-bar-fill" style={{ width: `${Math.min(100, (usage.todayTotal / usage.limit) * 100).toFixed(1)}%`, background: usage.todayTotal >= usage.limit ? "var(--color-text-danger)" : usage.todayTotal >= usage.limit * 0.8 ? "var(--color-text-warning)" : "var(--color-accent)" }} /></div>
163	          )}
164	          {usage.byModel && usage.byModel.length > 0 && (() => {
165	            const liveByModel = new Map((providerLive ?? []).map((r) => [r.model, r]));
166	            return (
167	              <div className="usage-models">
168	                <div className="usage-models-head">모델별 사용량 · 한도 (오늘)</div>
169	                {usage.byModel!.map((m) => {
170	                  const meta = PROV_META[m.provider] || PROV_META.unknown;
171	                  const name = m.model.includes("/") ? m.model.slice(m.model.lastIndexOf("/") + 1) : m.model; // 'openai/gpt-oss-120b' → 'gpt-oss-120b'
172	                  const live = liveByModel.get(m.model);
173	                  const hasLive = !!live && live.limitRequests != null && live.remainingRequests != null;
174	                  // ★공급자가 준 실값(정확) 우선★ — Groq 헤더의 키 전체 잔여로 사용량 산정. 없으면 이 서버가 센 추정치.
175	                  const used = hasLive ? Math.max(0, live!.limitRequests! - live!.remainingRequests!) : (m.requests ?? 0);
176	                  const lim = hasLive ? live!.limitRequests! : (m.reqLimit ?? 0);
177	                  const hasLimit = lim > 0;
178	                  const over = hasLimit && used > lim;
179	                  const pct = hasLimit ? Math.min(100, (used / lim) * 100) : 0;
180	                  return (
181	                    <div key={m.model} className="usage-model-row" style={m.disabled ? { opacity: 0.55 } : undefined}>
182	                      <div className="usage-model-top">
183	                        <span className="usage-model-name">{name}
184	                          <span className="usage-model-tag" style={{ color: meta.color }}>{m.plan || meta.tag}</span>
185	                          {m.kind === "backup" && <span className="usage-model-tag" style={{ color: "var(--color-text-tertiary)" }}>백업</span>}
186	                          {m.disabled && <span className="usage-model-tag" style={{ color: "var(--color-text-tertiary)" }}>관리자 꺼짐</span>}
187	                          <span className="usage-model-tag" style={{ color: hasLive ? "var(--color-text-success)" : "var(--color-text-tertiary)" }}>{hasLive ? "공급자 실시간" : "추정"}</span>
188	                        </span>
189	                        <span className="usage-model-tok">
190	                          {hasLimit
191	                            ? <>요청 {fmt(used)}/{fmt(lim)}{over && <b style={{ color: "var(--color-text-danger)" }}> · 초과</b>}</>
192	                            : m.provider === "codex"
193	                              ? <>요청 {fmt(used)} · 구독 한도(5h·주간)는 <a href="https://chatgpt.com" target="_blank" rel="noreferrer">codex /status·웹</a></>
194	                              : <>요청 {fmt(used)} · 무제한</>}
195	                          {hasLive && live!.remainingTokens != null && live!.limitTokens != null
196	                            ? <> · 분당 토큰 {fmt(live!.remainingTokens)}/{fmt(live!.limitTokens)} 남음</>
197	                            : <> · {fmt(m.tokens)} 토큰</>}
198	                        </span>
199	                      </div>
200	                      {hasLimit && (
201	                        <div className="usage-model-bar">
202	                          <div className="usage-model-fill" style={{ width: `${pct.toFixed(1)}%`, background: over ? "var(--color-text-danger)" : meta.color }} />
203	                        </div>
204	                      )}
205	                    </div>
206	                  );
207	                })}
208	                <p className="set-note" style={{ marginTop: 6 }}>
209	                  <b style={{ color: "var(--color-text-success)" }}>공급자 실시간</b>은 Groq가 응답 헤더로 주는 <b>키 전체 실값</b>(가장 정확)으로, <b>Groq 모델로 질의·분석한 뒤 그 모델에 표시</b>됩니다(Groq만 실시간 잔여 헤더 제공).<br /><b>Gemini는 실시간 잔여 API가 없어</b> 항상 <b>추정</b>(이 앱이 센 호출 수)이며, 정확한 값은 <a href="https://console.groq.com" target="_blank" rel="noreferrer">Groq</a>·<a href="https://aistudio.google.com" target="_blank" rel="noreferrer">Google AI Studio</a> 콘솔이 기준입니다.<br />막대는 일일 요청 수(자료 1개 업로드 = 1건), <b>사내(ollama) 모델은 무제한</b>.
210	                </p>
211	                <p className="set-note" style={{ marginTop: 4 }}><b>백업</b>은 1순위 한도가 차면 자동 전환되는 모델입니다(한도는 모델마다 별개).</p>
212	              </div>
213	            );
214	          })()}
215	          {Object.keys(usage.byKind).length > 0 && (
216	            <Row icon={IconCoin} label="종류별(7일)">
217	              <span style={{ fontSize: 12.5 }}>{Object.entries(usage.byKind).map(([k, v]) => `${KIND_LABEL[k] || k} ${fmt(v)}`).join(" · ")}</span>
218	            </Row>
219	          )}
220	          {usage.adminTodayTotal != null && (
221	            <Row icon={IconShieldCheck} label="전체(오늘·관리자)"><span>{fmt(usage.adminTodayTotal)} 토큰</span></Row>
222	          )}
223	          <p className="set-note">입력+출력 토큰 합계. 한도는 <code>DAILY_TOKEN_LIMIT</code>(미설정 시 무제한). 초과 시 질의·업로드가 일시 차단됩니다.</p>
224	        </section>
225	
226	        {/* 모델 관리 (관리자 토글) */}
227	        {modelList.length > 0 && (
228	          <section className="set-card">
229	            <div className="set-card-head"><IconCpu size={14} style={{ verticalAlign: "-2px", marginRight: 5 }} />모델 관리{profile.isAdmin ? " (관리자)" : ""}</div>
230	            <p className="set-note" style={{ marginTop: 0 }}>
231	              선택기의 1순위 모델과, 한도 초과 시 자동으로 쓰이는 <b>↳ 백업</b> 모델 전체입니다.
232	              {profile.isAdmin ? " 각 모델을 켜고 끌 수 있습니다(끄면 선택기·자동 폴백에서 모두 제외)." : " 켜고 끄기는 관리자만 가능합니다."}
233	            </p>
234	            <div className="model-admin-list">
235	              {modelList.map((m) => {
236	                const name = m.label.replace(/^↳ 백업 · /, "");
237	                const adminEditable = Boolean(profile.isAdmin) && m.available !== false;
238	                return (
239	                  <div key={m.id} className={`model-admin-row${m.kind === "backup" ? " backup" : ""}`}>
240	                    <div className="model-admin-info">
241	                      <span className="model-admin-name">{m.kind === "backup" ? "↳ " : ""}{name}</span>
242	                      <span className="model-admin-meta">{m.kind === "backup" ? "백업" : "1순위"}{m.available === false ? " · 키 없음" : ""}{m.adminDisabled ? " · 꺼짐" : ""}</span>
243	                    </div>
244	                    <label className={`mini-switch${m.enabled ? " on" : ""}${adminEditable ? "" : " disabled"}`} title={profile.isAdmin ? (m.available === false ? "키가 없어 켤 수 없습니다" : "사용 가능 여부") : "관리자만 변경 가능"}>
245	                      <input type="checkbox" role="switch" checked={m.enabled} disabled={!adminEditable} onChange={(e) => toggleModel(m.id, e.target.checked)} />
246	                      <span className="mini-switch-track"><span className="mini-switch-thumb" /></span>
247	                    </label>
248	                  </div>
249	                );
250	              })}
251	            </div>
252	          </section>
253	        )}
254	
255	        {/* 워크스페이스 */}
256	        <section className="set-card">
257	          <div className="set-card-head">내 워크스페이스</div>
258	          <div className="set-scope-list">
259	            {scopes.map((s) => {
260	              const I = KIND_ICON[s.kind];
261	              return (
262	                <div key={s.id} className="set-scope">
263	                  <I size={15} />
264	                  <span className="set-scope-name">{s.name}</span>
265	                  {s.isOwner && <IconStar size={12} className="set-star" />}
266	                  <span className="set-scope-kind">
267	                    {s.kind === "common" ? "공통" : s.kind === "personal" ? "개인" : s.isOwner ? "소유자" : "멤버"}
268	                  </span>
269	                </div>
270	              );
271	            })}
272	          </div>
273	          <p className="set-note">
274	            {rooms.length > 0
275	              ? `참여 중인 프로젝트 룸 ${rooms.length}개. 룸 생성·초대는 곧 제공됩니다.`
276	              : "아직 참여한 프로젝트 룸이 없습니다. 룸 생성·초대는 곧 제공됩니다."}
277	          </p>
278	        </section>
279	
280	        {/* 세션 */}
281	        <section className="set-card">
282	          <div className="set-card-head">세션</div>
283	          <Row icon={IconUserCircle} label="로그인 상태"><span className="set-ok"><IconCircleCheck size={14} />로그인됨</span></Row>
284	          <a className="set-logout" href="/auth/logout"><IconLogout size={15} />로그아웃</a>
285	        </section>
286	    </>
287	  );
288	  // 모달 모드(onClose): 페이지 래퍼 없이 내용만(카드·X·백드롭은 AppShell이 제공).
289	  if (onClose) return <div className="set-wrap set-modal-wrap">{body}</div>;
290	  return (
291	    <div className="set-page"><div className="set-wrap">
292	      <a className="set-back" href="/"><IconArrowLeft size={15} />위키로 돌아가기</a>
293	      <h1 className="set-title">계정 설정</h1>
294	      {body}
295	    </div></div>
296	  );
297	}
