"use client";

import { useEffect, useState } from "react";
import {
  IconArrowLeft, IconUserCircle, IconMail, IconShieldCheck, IconShieldHalf,
  IconSun, IconMoon, IconLogout, IconCircleCheck, IconId, IconCalendar,
  IconBuildingCommunity, IconUsers, IconUser, IconStar, IconCoin, IconCpu,
} from "@tabler/icons-react";

type ScopeKind = "common" | "personal" | "project";
interface ScopeLite { id: string; kind: ScopeKind; name: string; isOwner: boolean }
interface Profile {
  name: string; email: string; role: string; isAdmin?: boolean;
  isSso: boolean; verified: boolean; createdAt: string; initials: string;
}
interface ModelLite {
  id: string; label: string; provider: string; enabled: boolean;
  kind?: "primary" | "backup"; backupOf?: string; available?: boolean; adminDisabled?: boolean; note?: string;
}
interface ModelUsage { model: string; tokens: number; provider: string; requests?: number; reqLimit?: number; plan?: string; disabled?: boolean; kind?: "primary" | "backup" }
interface Usage {
  todayTotal: number; limit: number;
  byKind: Record<string, number>;
  byDay: [string, number][];
  byModel?: ModelUsage[];
  adminTodayTotal: number | null;
}
// 공급자(Groq) 실시간 잔여 스냅샷 — 키 전체 기준(배포+로컬 합산). 분당(RPM/TPM)·마지막 호출 시점.
interface ProviderLive {
  model: string;
  limitRequests: number | null; remainingRequests: number | null; resetRequests: string | null;
  limitTokens: number | null; remainingTokens: number | null; resetTokens: string | null;
  at: string;
}
const fmt = (n: number) => n.toLocaleString();
const KIND_LABEL: Record<string, string> = { query: "질의", ingest: "인제스트", websearch: "웹검색" };
// 공급자별 막대 색 + 표시 라벨(모델별 사용량 바)
const PROV_META: Record<string, { color: string; tag: string }> = {
  gemini: { color: "#f59e0b", tag: "외부·Google" },
  "openai-compat": { color: "#06b6d4", tag: "외부·Groq" },
  anthropic: { color: "#a855f7", tag: "Claude·유료" },
  ollama: { color: "#22c55e", tag: "사내·무료" },
  codex: { color: "#10a37f", tag: "구독·OpenAI" },
  unknown: { color: "var(--color-text-tertiary)", tag: "기타" },
};

const KIND_ICON: Record<ScopeKind, typeof IconUser> = {
  common: IconBuildingCommunity,
  project: IconUsers,
  personal: IconUser,
};

function Row({ icon: I, label, children }: { icon: typeof IconUser; label: string; children: React.ReactNode }) {
  return (
    <div className="set-row">
      <div className="set-row-key"><I size={15} />{label}</div>
      <div className="set-row-val">{children}</div>
    </div>
  );
}

export default function SettingsView({ profile, scopes, usage: usageProp, models, providerLive, onClose }: { profile: Profile; scopes: ScopeLite[]; usage: Usage; models?: ModelLite[]; providerLive?: ProviderLive[]; onClose?: () => void }) {
  const [dark, setDark] = useState(false);
  useEffect(() => { setDark(document.documentElement.classList.contains("dark")); }, []);

  // 사용량(게이지)은 상태로 — 모델 토글 후 재조회해 즉시 반영(prop은 모달/페이지 열릴 때 1회 계산이라 그대로 두면 stale).
  const [usage, setUsage] = useState<Usage>(usageProp);
  useEffect(() => { setUsage(usageProp); }, [usageProp]);

  // 모델 관리(관리자 토글). 낙관적 업데이트로 즉시 반영(깜빡임·금지커서 방지), 실패 시 롤백.
  const [modelList, setModelList] = useState<ModelLite[]>(models || []);
  useEffect(() => { if (models) setModelList(models); }, [models]);
  async function toggleModel(id: string, enabled: boolean) {
    setModelList((list) => list.map((m) => (m.id === id ? { ...m, enabled, adminDisabled: !enabled } : m)));
    try {
      const res = await fetch("/api/admin/models", {
        method: "POST", headers: { "content-type": "application/json" },
        body: JSON.stringify({ modelId: id, enabled }),
      });
      const d = await res.json();
      if (res.ok && d.models) setModelList(d.models);
      else throw new Error();
      // ★게이지(usage.byModel)도 갱신★ — 켠/끈 모델이 사용량 막대에 즉시 반영되도록 계정 데이터 재조회.
      try {
        const acc = await fetch("/api/account", { cache: "no-store" });
        if (acc.ok) { const aj = await acc.json(); if (aj.usage) setUsage(aj.usage); if (aj.models) setModelList(aj.models); }
      } catch { /* 게이지 갱신 실패는 무시(토글 자체는 성공) */ }
    } catch {
      setModelList((list) => list.map((m) => (m.id === id ? { ...m, enabled: !enabled, adminDisabled: enabled } : m)));
    }
  }

  function setTheme(next: boolean) {
    document.documentElement.classList.toggle("dark", next);
    document.cookie = `llmwiki_theme=${next ? "dark" : "light"}; path=/; max-age=31536000; samesite=lax`;
    setDark(next);
  }

  const rooms = scopes.filter((s) => s.kind === "project");

  const body = (
    <>
        {/* 프로필 */}
        <section className="set-card">
          <div className="set-card-head">프로필</div>
          <div className="set-profile">
            <div className="set-avatar">{profile.initials}</div>
            <div>
              <div className="set-name">{profile.name}</div>
              <div className="set-sub">{profile.email}</div>
            </div>
          </div>
          <div className="set-rows">
            <Row icon={IconMail} label="이메일">
              <span>{profile.email}</span>
              <span className="set-badge muted">인트라넷에서 관리</span>
            </Row>
            <Row icon={profile.role === "ADMIN" ? IconShieldCheck : IconShieldHalf} label="역할">
              <span className={`set-badge ${profile.role === "ADMIN" ? "accent" : "muted"}`}>
                {profile.role === "ADMIN" ? "관리자 (ADMIN)" : "일반 (USER)"}
              </span>
            </Row>
            <Row icon={IconId} label="계정 유형">
              {profile.isSso
                ? <span className="set-badge accent">인트라넷 SSO 계정</span>
                : <span className="set-badge muted">임시 계정</span>}
            </Row>
            <Row icon={IconCircleCheck} label="이메일 인증">
              {profile.verified
                ? <span className="set-ok"><IconCircleCheck size={14} />인증됨{profile.isSso ? " · 인트라넷" : ""}</span>
                : <span className="set-badge warn">미인증</span>}
            </Row>
            <Row icon={IconCalendar} label="가입일"><span>{profile.createdAt.slice(0, 10)}</span></Row>
          </div>
          <p className="set-note">이름·이메일은 인트라넷 SSO에서 동기화되어 이곳에서 수정할 수 없습니다.</p>
        </section>

        {/* 표시 환경 */}
        <section className="set-card">
          <div className="set-card-head">표시 환경</div>
          <Row icon={dark ? IconMoon : IconSun} label="테마">
            <div className="set-seg">
              <button className={`set-seg-btn${!dark ? " active" : ""}`} onClick={() => setTheme(false)}>
                <IconSun size={14} />라이트
              </button>
              <button className={`set-seg-btn${dark ? " active" : ""}`} onClick={() => setTheme(true)}>
                <IconMoon size={14} />다크
              </button>
            </div>
          </Row>
          <p className="set-note">선택한 테마는 이 브라우저에 저장되어 다음 접속에도 유지됩니다.</p>
        </section>

        {/* 토큰 사용량 (비용) */}
        <section className="set-card">
          <div className="set-card-head"><IconCoin size={14} style={{ verticalAlign: "-2px", marginRight: 5 }} />토큰 사용량</div>
          <Row icon={IconCoin} label="오늘 사용">
            <span style={{ fontWeight: 600 }}>{fmt(usage.todayTotal)}</span>
            <span style={{ color: "var(--color-text-tertiary)" }}>토큰{usage.limit > 0 ? ` / ${fmt(usage.limit)} 한도` : " (한도 없음)"}</span>
          </Row>
          {usage.limit > 0 && (
            <div className="cost-bar"><div className="cost-bar-fill" style={{ width: `${Math.min(100, (usage.todayTotal / usage.limit) * 100).toFixed(1)}%`, background: usage.todayTotal >= usage.limit ? "var(--color-text-danger)" : usage.todayTotal >= usage.limit * 0.8 ? "var(--color-text-warning)" : "var(--color-accent)" }} /></div>
          )}
          {usage.byModel && usage.byModel.length > 0 && (() => {
            const liveByModel = new Map((providerLive ?? []).map((r) => [r.model, r]));
            return (
              <div className="usage-models">
                <div className="usage-models-head">모델별 사용량 · 한도 (오늘)</div>
                {usage.byModel!.map((m) => {
                  const meta = PROV_META[m.provider] || PROV_META.unknown;
                  const name = m.model.includes("/") ? m.model.slice(m.model.lastIndexOf("/") + 1) : m.model; // 'openai/gpt-oss-120b' → 'gpt-oss-120b'
                  const live = liveByModel.get(m.model);
                  const hasLive = !!live && live.limitRequests != null && live.remainingRequests != null;
                  // ★공급자가 준 실값(정확) 우선★ — Groq 헤더의 키 전체 잔여로 사용량 산정. 없으면 이 서버가 센 추정치.
                  const used = hasLive ? Math.max(0, live!.limitRequests! - live!.remainingRequests!) : (m.requests ?? 0);
                  const lim = hasLive ? live!.limitRequests! : (m.reqLimit ?? 0);
                  const hasLimit = lim > 0;
                  const over = hasLimit && used > lim;
                  const pct = hasLimit ? Math.min(100, (used / lim) * 100) : 0;
                  return (
                    <div key={m.model} className="usage-model-row" style={m.disabled ? { opacity: 0.55 } : undefined}>
                      <div className="usage-model-top">
                        <span className="usage-model-name">{name}
                          <span className="usage-model-tag" style={{ color: meta.color }}>{m.plan || meta.tag}</span>
                          {m.kind === "backup" && <span className="usage-model-tag" style={{ color: "var(--color-text-tertiary)" }}>백업</span>}
                          {m.disabled && <span className="usage-model-tag" style={{ color: "var(--color-text-tertiary)" }}>관리자 꺼짐</span>}
                          <span className="usage-model-tag" style={{ color: hasLive ? "var(--color-text-success)" : "var(--color-text-tertiary)" }}>{hasLive ? "공급자 실시간" : "추정"}</span>
                        </span>
                        <span className="usage-model-tok">
                          {hasLimit
                            ? <>요청 {fmt(used)}/{fmt(lim)}{over && <b style={{ color: "var(--color-text-danger)" }}> · 초과</b>}</>
                            : m.provider === "codex"
                              ? <>요청 {fmt(used)} · 구독 한도(5h·주간)는 <a href="https://chatgpt.com" target="_blank" rel="noreferrer">codex /status·웹</a></>
                              : <>요청 {fmt(used)} · 무제한</>}
                          {hasLive && live!.remainingTokens != null && live!.limitTokens != null
                            ? <> · 분당 토큰 {fmt(live!.remainingTokens)}/{fmt(live!.limitTokens)} 남음</>
                            : <> · {fmt(m.tokens)} 토큰</>}
                        </span>
                      </div>
                      {hasLimit && (
                        <div className="usage-model-bar">
                          <div className="usage-model-fill" style={{ width: `${pct.toFixed(1)}%`, background: over ? "var(--color-text-danger)" : meta.color }} />
                        </div>
                      )}
                    </div>
                  );
                })}
                <p className="set-note" style={{ marginTop: 6 }}>
                  <b style={{ color: "var(--color-text-success)" }}>공급자 실시간</b>은 Groq가 응답 헤더로 주는 <b>키 전체 실값</b>(가장 정확)으로, <b>Groq 모델로 질의·분석한 뒤 그 모델에 표시</b>됩니다(Groq만 실시간 잔여 헤더 제공).<br /><b>Gemini는 실시간 잔여 API가 없어</b> 항상 <b>추정</b>(이 앱이 센 호출 수)이며, 정확한 값은 <a href="https://console.groq.com" target="_blank" rel="noreferrer">Groq</a>·<a href="https://aistudio.google.com" target="_blank" rel="noreferrer">Google AI Studio</a> 콘솔이 기준입니다.<br />막대는 일일 요청 수(자료 1개 업로드 = 1건), <b>사내(ollama) 모델은 무제한</b>.
                </p>
                <p className="set-note" style={{ marginTop: 4 }}><b>백업</b>은 1순위 한도가 차면 자동 전환되는 모델입니다(한도는 모델마다 별개).</p>
              </div>
            );
          })()}
          {Object.keys(usage.byKind).length > 0 && (
            <Row icon={IconCoin} label="종류별(7일)">
              <span style={{ fontSize: 12.5 }}>{Object.entries(usage.byKind).map(([k, v]) => `${KIND_LABEL[k] || k} ${fmt(v)}`).join(" · ")}</span>
            </Row>
          )}
          {usage.adminTodayTotal != null && (
            <Row icon={IconShieldCheck} label="전체(오늘·관리자)"><span>{fmt(usage.adminTodayTotal)} 토큰</span></Row>
          )}
          <p className="set-note">입력+출력 토큰 합계. 한도는 <code>DAILY_TOKEN_LIMIT</code>(미설정 시 무제한). 초과 시 질의·업로드가 일시 차단됩니다.</p>
        </section>

        {/* 모델 관리 (관리자 토글) */}
        {modelList.length > 0 && (
          <section className="set-card">
            <div className="set-card-head"><IconCpu size={14} style={{ verticalAlign: "-2px", marginRight: 5 }} />모델 관리{profile.isAdmin ? " (관리자)" : ""}</div>
            <p className="set-note" style={{ marginTop: 0 }}>
              선택기의 1순위 모델과, 한도 초과 시 자동으로 쓰이는 <b>↳ 백업</b> 모델 전체입니다.
              {profile.isAdmin ? " 각 모델을 켜고 끌 수 있습니다(끄면 선택기·자동 폴백에서 모두 제외)." : " 켜고 끄기는 관리자만 가능합니다."}
            </p>
            <div className="model-admin-list">
              {modelList.map((m) => {
                const name = m.label.replace(/^↳ 백업 · /, "");
                const adminEditable = Boolean(profile.isAdmin) && m.available !== false;
                return (
                  <div key={m.id} className={`model-admin-row${m.kind === "backup" ? " backup" : ""}`}>
                    <div className="model-admin-info">
                      <span className="model-admin-name">{m.kind === "backup" ? "↳ " : ""}{name}</span>
                      <span className="model-admin-meta">{m.kind === "backup" ? "백업" : "1순위"}{m.available === false ? " · 키 없음" : ""}{m.adminDisabled ? " · 꺼짐" : ""}</span>
                    </div>
                    <label className={`mini-switch${m.enabled ? " on" : ""}${adminEditable ? "" : " disabled"}`} title={profile.isAdmin ? (m.available === false ? "키가 없어 켤 수 없습니다" : "사용 가능 여부") : "관리자만 변경 가능"}>
                      <input type="checkbox" role="switch" checked={m.enabled} disabled={!adminEditable} onChange={(e) => toggleModel(m.id, e.target.checked)} />
                      <span className="mini-switch-track"><span className="mini-switch-thumb" /></span>
                    </label>
                  </div>
                );
              })}
            </div>
          </section>
        )}

        {/* 워크스페이스 */}
        <section className="set-card">
          <div className="set-card-head">내 워크스페이스</div>
          <div className="set-scope-list">
            {scopes.map((s) => {
              const I = KIND_ICON[s.kind];
              return (
                <div key={s.id} className="set-scope">
                  <I size={15} />
                  <span className="set-scope-name">{s.name}</span>
                  {s.isOwner && <IconStar size={12} className="set-star" />}
                  <span className="set-scope-kind">
                    {s.kind === "common" ? "공통" : s.kind === "personal" ? "개인" : s.isOwner ? "소유자" : "멤버"}
                  </span>
                </div>
              );
            })}
          </div>
          <p className="set-note">
            {rooms.length > 0
              ? `참여 중인 프로젝트 룸 ${rooms.length}개. 룸 생성·초대는 곧 제공됩니다.`
              : "아직 참여한 프로젝트 룸이 없습니다. 룸 생성·초대는 곧 제공됩니다."}
          </p>
        </section>

        {/* 세션 */}
        <section className="set-card">
          <div className="set-card-head">세션</div>
          <Row icon={IconUserCircle} label="로그인 상태"><span className="set-ok"><IconCircleCheck size={14} />로그인됨</span></Row>
          <a className="set-logout" href="/auth/logout"><IconLogout size={15} />로그아웃</a>
        </section>
    </>
  );
  // 모달 모드(onClose): 페이지 래퍼 없이 내용만(카드·X·백드롭은 AppShell이 제공).
  if (onClose) return <div className="set-wrap set-modal-wrap">{body}</div>;
  return (
    <div className="set-page"><div className="set-wrap">
      <a className="set-back" href="/"><IconArrowLeft size={15} />위키로 돌아가기</a>
      <h1 className="set-title">계정 설정</h1>
      {body}
    </div></div>
  );
}
